function figure(p){const g='g'+p.id;return `<svg viewBox="0 0 200 230" aria-hidden="true"><defs><linearGradient id="${g}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${p.shirt}"/><stop offset="1" stop-color="#0d0e12" stop-opacity=".55"/></linearGradient><radialGradient id="${g}f" cx=".4" cy=".35" r=".7"><stop offset="0" stop-color="#fff" stop-opacity=".35"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs>
${p.hs==='long'?`<path d="M58 92c-4-40 18-60 42-60s48 18 42 62c4 30-4 52-10 62H68c-8-12-14-34-10-64z" fill="${p.hair}"/>`:''}
<path d="M20 230c4-46 38-72 80-72s76 26 80 72z" fill="${p.shirt}"/><path d="M20 230c4-46 38-72 80-72s76 26 80 72z" fill="url(#${g})"/><path d="M82 158l18 18 18-18" stroke="#fff" stroke-width="3" fill="none" opacity=".5" stroke-linecap="round"/>
<rect x="85" y="118" width="30" height="44" rx="14" fill="${p.skin}"/><rect x="85" y="126" width="30" height="13" fill="#000" opacity=".1"/>
<ellipse cx="100" cy="88" rx="34" ry="40" fill="${p.skin}"/><ellipse cx="100" cy="88" rx="34" ry="40" fill="url(#${g}f)"/>
${p.hs==='long'?`<path d="M66 86c0-30 16-46 34-46s33 16 33 44c-10-14-22-22-36-20-12 2-22 10-31 22z" fill="${p.hair}"/>`:`<path d="M65 84c0-31 16-46 35-46 20 0 35 14 35 42-6-12-18-19-35-19s-27 8-35 23z" fill="${p.hair}"/>`}
<g class="blink"><circle cx="88" cy="92" r="3.6" fill="#231F1A"/><circle cx="112" cy="92" r="3.6" fill="#231F1A"/></g><path d="M89 108q11 8 22 0" stroke="#231F1A" stroke-width="3" fill="none" stroke-linecap="round"/>
<ellipse cx="80" cy="102" rx="6" ry="3.5" fill="#FF7A6B" opacity=".22"/><ellipse cx="120" cy="102" rx="6" ry="3.5" fill="#FF7A6B" opacity=".22"/></svg>`}
const bust=p=>`<span class="bust">${figure(p)}</span>`;
function stage3d(p){const f=p.facts||[];return `<div class="a3d" style="--c:${p.c}" data-tilt><div class="a3d-sky"></div><div class="a3d-ring r1"></div><div class="a3d-ring r2"></div><div class="a3d-fig">${figure(p)}</div><div class="a3d-ped"><i></i></div>${f.slice(0,4).map((x,i)=>`<span class="orbit o${i}"><b>${x[1]}</b><small>${x[0]}</small></span>`).join('')}<span class="a3d-badge">${p.v} · ${p.stat}</span></div>`}
function avatarStudio(p,tab,list,base){const T=[['profile','Profile'],['deep','Full profile'],['use','Use it'],['evidence','Evidence']];const L=x=>`<ul class="ticks dots">${x.map(i=>`<li>${i}</li>`).join('')}</ul>`;
const card=(i,t,c)=>`<section class="sp" style="--i:${i}"><h3>${t}</h3>${c}</section>`;let body='';
if(tab==='profile')body=`<div class="studio"><div class="specs left">${card(0,`${ic('user',16)}At a glance`,`<dl class="facts">${(p.facts||[]).map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`)}${card(1,`${ic('compass',16)}Where he is now`,`<p>${p.now}</p>`)}${card(2,`${ic('dollar',16)}Pays for`,L(p.pays||[]))}</div>
<div class="studio-c">${stage3d(p)}<h1>${p.short}</h1><p class="over">${p.role}</p><div class="chiprow" style="justify-content:center">${(p.used||[]).map(u=>`<span class="tag">${ic('funnels',12)} ${u}</span>`).join('')}</div></div>
<div class="specs right">${card(3,`${ic('target',16)}Wants`,L(p.wants||[]))}${card(4,`${ic('alert',16)}Scared of`,L(p.scared||[]))}${card(5,`${ic('globe',16)}Where to reach him`,L(p.reach||[]))}</div></div>
<div class="rootbelief"><span class="over">Root belief · break it gently</span><q>${p.root}</q><a class="btn ghost sm" href="#/${base}deep#beliefs">All beliefs</a></div>
<div class="oneliner"><span class="over">One-line version</span><p>${p.oneliner}</p><button class="btn quiet sm" data-act="toast:Copied.:ok">${ic('copy',16)}Copy</button></div>`;
if(tab==='deep'){const ch=[['market','Market map',100],['qual','Qualification',100],['basic','Basic profile',100],['drives','What drives him',80],['beliefs','Beliefs',100],['desires','External vs internal desires',100],['filter','Best vs worst customer',100],['problems','Problems, now and next',70],['niche','Niche statement',100],['next','What to do next',40],['notes','Context notes',20]];
body=`<div class="deep"><nav class="chapters" aria-label="Chapters"><p class="over">Chapters</p>${ch.map(([k,l,d],i)=>`<a href="#/${base}deep" data-act="jump:${k}"><span class="ring xs" style="--v:${d}"></span>${i+1}. ${l}</a>`).join('')}<button class="addrow" data-act="toast:Add your own chapter or field. Every section can grow.">${ic('plus',16)}Add a chapter</button></nav><div class="chap-body">
<section id="c-market" class="chap"><h2>1. Market map</h2><div class="mmap"><span class="mm core">${p.market.core}<small>Core market</small></span><span class="mm-l"></span><span class="mm sub">${p.market.sub}<small>Submarket</small></span><span class="mm-l"></span><div class="mm-n">${p.market.niches.map(([n,s,on])=>`<span class="mm niche ${on?'on':''}">${n}<small>${s}</small></span>`).join('')}</div></div></section>
<section id="c-qual" class="chap"><h2>2. Qualification · Russell’s 3 questions</h2><div class="grid3">${p.qual.map(([q,a],i)=>`<div class="qcard"><span class="light">${ic('check',18,'',2.6)}</span><b>${q}</b><p>${a}</p></div>`).join('')}</div><p class="okline">${ic('check',16,'',2.6)}Green light on all three. Niche validated.</p></section>
<section id="c-basic" class="chap"><h2>3. Basic profile</h2><dl class="facts wide">${p.facts.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><p><b>Studying:</b> Alex Hormozi, Russell Brunson, Pedro Moreira</p></section>
<section id="c-drives" class="chap"><h2>4. What drives him</h2><div class="grid2"><div><p class="sec-t">Wants</p>${L(p.wants)}</div><div><p class="sec-t">Values</p><div class="chiprow">${p.values.map(v=>`<span class="tag">${v}</span>`).join('')}</div></div></div><div class="callout"><b>Who he wants to be</b><p>${p.identity}</p><small>Sell the identity, never the celebrity.</small></div><div class="callout"><b>How he learns</b><p>${p.learn}</p><small>Every lesson connects to the outcome, not the topic.</small></div></section>
<section id="c-beliefs" class="chap"><h2>5. Beliefs</h2><div class="tblwrap"><table class="tbl"><thead><tr><th>About</th><th>Belief</th><th>Verdict</th></tr></thead><tbody>${p.beliefs.map(([a,b,v])=>`<tr><td data-l="About">${a}</td><td class="t1">“${b}”</td><td data-l="Verdict">${v==='T'?'<span class="pill blue">True · honour it</span>':'<span class="pill danger">False · break gently</span>'}</td></tr>`).join('')}</tbody></table></div><p class="hint" style="margin-top:8px">Rule: every ad, email and call either honours a true belief or gently breaks a false one. Never mock either.</p></section>
<section id="c-desires" class="chap"><h2>6. External vs internal desires</h2><div class="grid2"><div class="des ext"><p class="sec-t">${ic('megaphone',16)}External · says out loud <span class="pill">Use in ads and hooks</span></p>${p.ext.map(x=>`<p class="quote">${x}</p>`).join('')}</div><div class="des int"><p class="sec-t">${ic('heart',16)}Internal · feels, rarely says <span class="pill">Use in story and close</span></p>${p.int.map(x=>`<p class="quote">${x}</p>`).join('')}</div></div></section>
<section id="c-filter" class="chap"><h2>7. Best vs worst customer</h2><div class="grid2"><div class="fcol best"><p class="sec-t">${ic('check',16,'',2.6)}Fight for this John</p>${p.best.map(([t,w])=>`<div class="fitem"><b>${t}</b><small>${w}</small></div>`).join('')}</div><div class="fcol worst"><p class="sec-t">${ic('x',16,'',2.6)}Politely refund this John</p>${p.worst.map(([t,w])=>`<div class="fitem"><b>${t}</b><small>${w}</small></div>`).join('')}</div></div></section>
<section id="c-problems" class="chap"><h2>8. Problems, now and next</h2><div class="pmx"><span></span><b>Now</b><b>If nothing changes</b>${Object.entries(p.problems).map(([k,L2])=>`<b class="rowh">${k}</b><div>${L2.map(x=>`<p>${x[0]}</p>`).join('')}</div><div>${L2.map(x=>`<p class="fut">${x[1]}</p>`).join('')}</div>`).join('')}</div></section>
<section id="c-niche" class="chap"><h2>9. Niche statement</h2>${[['Full','I help course creators and coaches doing $5K–$30K a month build funnels that work, without wasting money on wrong paths.'],['Compact','We build the funnel layer between your offer and your traffic, so you can focus on your message.'],['One line',p.oneliner]].map(([k,t])=>`<div class="stmt"><span class="pill">${k}</span><p>${t}</p><button class="iconbtn" data-act="toast:Copied.:ok" aria-label="Copy">${ic('copy',16)}</button></div>`).join('')}</section>
<section id="c-next" class="chap"><h2>10. What to do next</h2><div class="checkl">${p.next.map(([t,w,d])=>`<div class="row ${d?'done':''}"><button class="cbx" role="checkbox" aria-checked="${!!d}" data-act="sub" aria-label="${t}"><i>${ic('check',14,'',3)}</i></button><div class="main"><b>${t}</b><small>${w==='week'?'This week':'Next 30 days'}</small></div><button class="btn quiet sm" data-act="toast:Sent to Tasks as “${t}”.:ok">→ Task</button></div>`).join('')}</div></section>
<section id="c-notes" class="chap"><h2>11. Context notes</h2><p class="tx2" contenteditable="true" style="padding:12px;border:1px dashed var(--line2);border-radius:12px">Add anything that doesn’t fit a chapter.</p></section></div></div>`}
if(tab==='use')body=`<p class="lede" style="margin:-6px 0 18px">Turn the profile into copy angles. Each card points back to the research it came from.</p><div class="cardgrid">${[['Hook','External desire','“Still not in the One Comma Club after the Challenge? Here’s the layer you’re missing.”','megaphone'],['Story','Internal desire','Open with the night he realised his family was waiting on this funnel.','heart'],['Objection','False belief: DFY is too expensive','Compare one month of wasted ads to the cost of a funnel that works.','xcircle'],['Proof','Best-customer trait','“He did 20% of the work. We did the funnel.”','star'],['Channel','Where to reach him','Comment with value under Brunson and Hormozi videos, then invite to the quiz.','globe'],['Filter question','Worst-customer trait','“Do you think an AI tool could build this for you?”','filter']].map(([t,s,c,i])=>`<div class="card"><span style="display:flex;gap:8px;align-items:center">${ic(i,18)}<b>${t}</b><span class="pill" style="margin-left:auto">${s}</span></span><p style="font:italic 400 17px/1.45 'Newsreader',serif;color:var(--text)">${c}</p><div class="foot"><button class="btn quiet sm" data-act="toast:Copied.:ok">${ic('copy',14)}Copy</button><button class="btn quiet sm" data-act="toast:Added to the Challenge funnel strategy.:ok">Add to strategy</button></div></div>`).join('')}</div>`;
if(tab==='evidence')body=`<div class="split"><section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">${ic('shield',16)}How sure are we?</p>${(p.ev||[]).map(([e,v,t])=>`<div class="why"><b>${e}</b><span class="pill ${t==='v'?'blue':'warn'}">${v}</span></div>`).join('')}<div class="notice" style="margin-top:12px">${ic('alert',18)}<span><b>Draft.</b> Confirm with 5 real Johns before locking v1.1.</span></div><button class="btn primary" style="margin-top:12px" data-act="toast:Interview note added.:ok">${ic('plus',18,'',2.2)}Log an interview</button></section><section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">${ic('hist',16)}Versions</p>${[['v1.0','11 Aug 2026','First draft from research'],['v0.9','2 Aug 2026','Short version']].map(([v,d,n])=>`<div class="ver" style="margin-bottom:8px"><b class="mono">${v}</b><span style="flex:1">${d} · ${n}</span><button class="btn quiet sm" data-act="toast:Opens a side-by-side comparison.">Compare</button></div>`).join('')}</section></div>`;
return `<div class="studio-wrap" style="--c:${p.c}">${focusBar('office',{title:`<b>${p.n}</b>`,sub:'Office › Funnels › Customer Avatars',back:list,right:`<span class="pill ${p.stat==='Validated'?'blue':'warn'}">${p.v} · ${p.stat}</span><span class="ring sm hide-m" style="--v:${p.done}" title="${p.done}% complete"><b>${p.done}%</b></span><button class="btn ghost sm hide-m" data-act="toast:Exports the profile as a PDF or Word file.">${ic('download',16)}Export</button><button class="btn primary sm" data-act="toast:Every section becomes editable, with Save and Cancel.">${ic('edit',16)}Edit</button>`})}<div class="studio-tabs">${T.map(([k,l])=>`<a href="#/${base}${k}" aria-selected="${k===tab}">${l}</a>`).join('')}</div><div class="studio-body">${body}</div></div>`}
ACT.jump=v=>{$('#c-'+v)?.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'})};
ACT.sub=(v,t)=>{const r=t.closest('.row'),d=r.classList.toggle('done');t.setAttribute('aria-checked',d)};
I.megaphone='<path d="M4 10v4h3l7 4V6L7 10zM17 9.5a3.5 3.5 0 0 1 0 5M19.5 7a7 7 0 0 1 0 10"/>';
document.addEventListener('pointermove',e=>{if(reduce)return;const s=e.target.closest?.('[data-tilt]');if(!s)return;const r=s.getBoundingClientRect();s.style.setProperty('--tx',((e.clientX-r.left)/r.width-.5)*14+'deg');s.style.setProperty('--ty',(-(e.clientY-r.top)/r.height+.5)*10+'deg')});
